('<lesson_id>', 'speaking', replace($blk${"title": "SPEAKING II 🎤", "needs_review": true, "html": "<p>Ответь на вопросы полными предложениями.</p><ol><li>What are you doing right now?</li><li>What gadgets have you got?</li><li>What's your favourite gadget?</li><li>Do you usually chat online with your friends or talk on the phone?</li><li>What music are you listening to these days?</li><li>Are you good at computer games?</li><li>What are you scared of?</li><li>Are your parents good at technology?</li></ol>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 13)
